import org.apache.commons.lang3.builder.*;

public class Scratch {
    static class Job {
        String title;
    }
    static class Person {
        String name;
        int age;
        boolean smoker;
        Job job;
    }

    public static void main(String[] args) {
        Person p = new Person();
        p.name = "John Doe";
        p.age = 33;
        p.smoker = false;
        p.job = new Job();
        p.job.title = "Manager";
        ReflectionToStringBuilder b = new ReflectionToStringBuilder(p, new MultilineRecursiveToStringStyle());
        System.out.println("FORCE=" + b.isForceAccessible());
        System.out.println("---PERSON---");
        System.out.println(b.toString());
        System.out.println("---END---");

        System.out.println("---INT ARRAY---");
        System.out.println(new ToStringBuilder(p, new MultilineRecursiveToStringStyle()).append("nums", new int[]{1,2,3}).toString());
        System.out.println("---END---");

        System.out.println("---EMPTY ARRAY---");
        System.out.println(new ToStringBuilder(p, new MultilineRecursiveToStringStyle()).append("nums", new int[]{}).toString());
        System.out.println("---END---");

        System.out.println("---NULL FIELD---");
        System.out.println(new ToStringBuilder(p, new MultilineRecursiveToStringStyle()).append("x", (Object) null).toString());
        System.out.println("---END---");

        System.out.println("---OBJ ARRAY WITH NESTED---");
        Job j2 = new Job(); j2.title = "Dev";
        System.out.println(new ToStringBuilder(p, new MultilineRecursiveToStringStyle()).append("jobs", new Object[]{j2}).toString());
        System.out.println("---END---");

        System.out.println("---PRIMITIVE WRAPPER---");
        System.out.println(new ToStringBuilder(p, new MultilineRecursiveToStringStyle()).append("i", Integer.valueOf(5), true).toString());
        System.out.println("---END---");

        System.out.println("---STRING FIELD---");
        System.out.println(new ToStringBuilder(p, new MultilineRecursiveToStringStyle()).append("s", "hello", true).toString());
        System.out.println("---END---");

        System.out.println("---REUSE SAME STYLE INSTANCE TWICE---");
        MultilineRecursiveToStringStyle style = new MultilineRecursiveToStringStyle();
        String r1 = new ToStringBuilder(p, style).append("a", 1).toString();
        String r2 = new ToStringBuilder(p, style).append("b", 2).toString();
        System.out.println(r1);
        System.out.println(r2);
        System.out.println("---END---");
    }
}
EOF
